static async Task PairAsync(BridgeConfig config, CancellationToken ct)
{
    Console.Write("请输入网页端生成的 6 位配对码：");
    var code = Console.ReadLine()?.Trim() ?? "";
    using var http = new HttpClient { BaseAddress = new Uri(config.ServerUrl) };
