    const session = requireAuth(request);
    const body = NotificationPrefsBody.parse(request.body);
    const user = await auth.updateAccount(session.userId, {
      notificationPrefs: body,
    });
    return {
      ok: true,
      notificationPrefs: user.notificationPrefs,
    };
  });

